"""Write docs/data_dictionary.md from the canonical schema and feature registry.

Run: python scripts/generate_data_dictionary.py
"""

from __future__ import annotations

from riskstream.config import PROJECT_ROOT
from riskstream.data.schema import CANONICAL_COLUMNS
from riskstream.features.registry import EXCLUDED_COLUMNS, get_registry


def main() -> None:
    reg = get_registry()
    lines = [
        "# Data dictionary",
        "",
        "Generated by `python scripts/generate_data_dictionary.py` from "
        "`src/riskstream/data/schema.py` and `src/riskstream/features/registry.py`. Do not edit by hand.",
        "",
        "## Canonical transaction columns",
        "",
        "| column | type | available when scoring | description |",
        "|---|---|---|---|",
    ]
    for c in CANONICAL_COLUMNS:
        lines.append(f"| `{c.name}` | {c.dtype} | {'yes' if c.available_at_inference else 'no'} | {c.description} |")
    lines += [
        "",
        f"## Model features (version {reg.version}, windows {list(reg.config.windows)} hours)",
        "",
        "Feature sets: " + "; ".join(f"`{k}` = {', '.join(v)}" for k, v in reg.config.feature_sets.items()) + ".",
        "",
        "Missing-value policy: `never` = always defined; `zero_is_true` = 0 means no prior events; "
        "`nan_undefined` = NaN when the statistic is undefined (trees route NaN natively; "
        "logistic regression imputes inside its serialized pipeline).",
        "",
        "| feature | group | source fields | calculation | missing | online | since |",
        "|---|---|---|---|---|---|---|",
    ]
    for s in reg.specs:
        lines.append(
            f"| `{s.name}` | {s.group} | {', '.join(s.source_fields)} | {s.calculation} | "
            f"{s.missing} | {'yes' if s.online_available else 'no'} | {s.version_added} |"
        )
    lines += ["", "## Columns excluded from features", "", "| column | reason |", "|---|---|"]
    lines += [f"| `{k}` | {v} |" for k, v in EXCLUDED_COLUMNS.items()]
    out = PROJECT_ROOT / "docs" / "data_dictionary.md"
    out.write_text("\n".join(lines) + "\n", encoding="utf-8")
    print(f"wrote {out}")


if __name__ == "__main__":
    main()
